static int check_vector(const unsigned char *comp,
                        zragf_size_t comp_size,
                        int windowBits)
{
    unsigned char out[512];
    zragf_stream is;
    int rc;

    memset(&is, 0, sizeof(is));
    rc = zragf_inflateInit2(&is, windowBits);
    if (rc != ZRAGF_OK) {
        fprintf(stderr, "inflateInit2 failed: %d\n", rc);
        return 1;
    }

    is.next_in = (zragf_u8 *)comp;
    is.avail_in = comp_size;
    is.next_out = out;
    is.avail_out = sizeof(out);
    rc = zragf_inflateZ(&is, ZRAGF_FINISH);
    zragf_inflateEndZ(&is);
    if (rc != ZRAGF_STREAM_END) {
        fprintf(stderr, "inflate failed: %d\n", rc);
        return 1;
    }

    if ((sizeof(kPayload) != (sizeof(out) - is.avail_out)) ||
        memcmp(out, kPayload, sizeof(kPayload)) != 0) {
        fprintf(stderr, "decoded payload mismatch\n");
        return 1;
    }

    return 0;
}

int main(void)
{
    if (check_vector(kRawStream, sizeof(kRawStream), -15)) return 1;
    if (check_vector(kZlibStream, sizeof(kZlibStream), 15)) return 1;
    if (check_vector(kGzipStream, sizeof(kGzipStream), 31)) return 1;
    puts("external compatibility vectors ok");
    return 0;
}
